    /** Base64 of the packed coverage for the icon at {@code index}. */
    public static String data(int index) {
        switch (index) {
            case 0: return join(ADD_BITS);
            case 1: return join(ARROW_BACK_BITS);
            case 2: return join(BRIGHTNESS_4_BITS);
            case 3: return join(BRIGHTNESS_HIGH_BITS);
            case 4: return join(BUILD_BITS);
            case 5: return join(CHECK_CIRCLE_BITS);
            case 6: return join(CHEVRON_LEFT_BITS);
            case 7: return join(CLOSE_BITS);
            case 8: return join(DELETE_BITS);
            case 9: return join(DOWNLOAD_BITS);
            case 10: return join(EDIT_BITS);
            case 11: return join(EXIT_TO_APP_BITS);
            case 12: return join(FOLDER_OPEN_BITS);
            case 13: return join(HOME_BITS);
            case 14: return join(KEYBOARD_BITS);
            case 15: return join(KEYBOARD_ARROW_DOWN_BITS);
            case 16: return join(KEYBOARD_ARROW_LEFT_BITS);
            case 17: return join(KEYBOARD_ARROW_RIGHT_BITS);
            case 18: return join(KEYBOARD_ARROW_UP_BITS);
            case 19: return join(MORE_VERT_BITS);
            case 20: return join(NORTH_EAST_BITS);
            case 21: return join(NORTH_WEST_BITS);
            case 22: return join(PHOTO_CAMERA_BITS);
            case 23: return join(PHOTO_LIBRARY_BITS);
            case 24: return join(PLAY_ARROW_BITS);
            case 25: return join(SAVE_BITS);
            case 26: return join(SCREEN_ROTATION_BITS);
            case 27: return join(SEARCH_BITS);
            case 28: return join(SETTINGS_BITS);
            case 29: return join(SHARE_BITS);
            case 30: return join(SORT_BITS);
            case 31: return join(SOUTH_EAST_BITS);
            case 32: return join(SOUTH_WEST_BITS);
            case 33: return join(SPEED_BITS);
            case 34: return join(STAR_BITS);
            case 35: return join(STAR_BORDER_BITS);
            case 36: return join(STOP_CIRCLE_BITS);
            case 37: return join(TUNE_BITS);
            case 38: return join(UNDO_BITS);
            case 39: return join(VIDEOCAM_BITS);
            case 40: return join(VIDEOGAME_ASSET_BITS);
            default: return null;
        }
    }

    private static String join(String[] parts) {
        StringBuilder text = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            text.append(parts[i]);
        }
        return text.toString();
    }

